#include "character_resources.hpp"
#include "asset_images.hpp"
#include "item_models.hpp"
#include <map>
#include <mutex>
#include <stdexcept>
namespace mu::viewer {
std::shared_ptr<const CharacterBody> load_character_body(const std::string& root,const CharacterResources& r){
 static std::mutex mutex;static std::map<std::string,std::shared_ptr<const CharacterBody>> bodies;
 std::lock_guard<std::mutex> guard(mutex);auto data=std::filesystem::weakly_canonical(std::filesystem::path(root)/"Data/Player");auto key=data.string()+r.key();auto found=bodies.find(key);if(found!=bodies.end())return found->second;
 // Load only required animation clips; cache complete validated bodies, bounded below.
 auto actions=equipped_actions(r,*mu::ui::load_item_catalog(data.parent_path(),"Eng"));unsigned attack=38;auto catalog=mu::ui::load_item_catalog(data.parent_path(),"Eng");auto right=r.attachments[0],left=r.attachments[1];if(left&&left->index/512==4&&left->index%512!=7)attack=50;else if(right){auto group=right->index/512,type=right->index%512;bool two=catalog->at(right->index).twoHand;if(group<=2)attack=two?43:39;else if(group==3)attack=(type==1||type==2)?46:47;else if(group==4&&type>=8&&type!=15)attack=51;else if(group==5)attack=two?148:39;}else if(left&&left->index/512<=2)attack=41;auto skeleton=mu::assets::load_model(data/"Player.bmd",{0,r.idle,r.walk,r.run,actions[0],actions[1],actions[2],146,147,attack});auto body=std::make_shared<CharacterBody>();body->combatActions={actions[0],actions[1],actions[2],146,147,attack};for(unsigned i=0;i<6;i++){auto action=body->combatActions[i];body->combat[i]=skeleton.clips.at(action);body->combatPeriods[i]=body->combat[i].size()-(skeleton.lockedPositions.at(action)?1:0);}body->bones=skeleton.bones;body->idle=skeleton.clips.at(r.idle);body->walk=skeleton.clips.at(r.walk);body->run=skeleton.clips.at(r.run);unsigned baseActions[]={r.idle,r.walk,r.run};for(unsigned i=0;i<3;i++)body->periods[i]=skeleton.clips.at(baseActions[i]).size()-(skeleton.lockedPositions.at(baseActions[i])?1:0);
 std::map<std::string,std::shared_ptr<const mu::assets::Image>> textures;
 for(unsigned i=0;i<r.models.size();i++){if(r.models[i].empty())throw std::runtime_error("Empty armor model path");auto model=mu::assets::load_model(data/r.models[i]);for(auto& mesh:model.meshes){for(const auto& v:mesh.vertices){if(v.bone<0||unsigned(v.bone)>=skeleton.bones.size()||unsigned(v.bone)>=model.bones.size()||model.bones[v.bone].name!=skeleton.bones[v.bone].name||model.bones[v.bone].parent!=skeleton.bones[v.bone].parent)throw std::runtime_error(r.models[i]+": original player bone binding mismatch");}auto path=resolve_model_texture(data,mesh.texture);auto textureKey=path.string();if(!textures.count(textureKey))textures[textureKey]=std::make_shared<mu::assets::Image>(decode_texture(path));body->meshes.push_back({std::move(mesh),textures.at(textureKey),i,r.armorItems[i]});}}
 for(unsigned i=0;i<r.attachments.size();i++)if(r.attachments[i])try{auto item=*r.attachments[i];auto path=item_model_path(data.parent_path(),item);if(path.empty()||!std::filesystem::exists(path)){std::fprintf(stderr,"[Equipment] slot %u model unavailable for %u:%u\n",i==2?7:i,item.index/512,item.index%512);continue;}
 auto model=mu::assets::load_model(path,{0});auto visual=std::make_shared<ActorVisual>();visual->effectDirectory=data.parent_path();visual->name=path.filename().string();visual->bones=model.bones;visual->idle=model.idlePoses;if(model.clips.count(0))visual->idle=model.clips.at(0);if(visual->idle.empty())visual->idle={model.bones};visual->idlePeriod=visual->idle.size();if(model.lockedPositions.count(0)&&model.lockedPositions.at(0)&&visual->idlePeriod>1)visual->idlePeriod--;visual->walk=visual->idle;visual->walkPeriod=visual->idlePeriod;visual->idleKeySpeed=i==2?.25:0;visual->scale=1;
 for(auto& mesh:model.meshes){auto texturePath=resolve_model_texture(path.parent_path(),mesh.texture);auto key=texturePath.string();if(!textures.count(key))textures[key]=std::make_shared<mu::assets::Image>(decode_texture(texturePath));visual->parts.push_back({std::move(mesh),textures.at(key),false,item});}body->attachments.push_back({i==2?7:i,item,visual});}catch(const std::exception& e){std::fprintf(stderr,"[Equipment] slot %u: %s\n",i==2?7:i,e.what());}
 if(bodies.size()>=16)bodies.clear();bodies.emplace(key,body);return body;
}
}
